    let B = ''; if (v.op2) v.op2.forEach((t, i) => { B += arc((X(i) + X(i + 1)) / 2 + 3, (X(i + 1) + X(i + 2)) / 2 - 3, 66, 26, 'lg') + K.t(X(i + 1), 44, t, 'tg'); });
